int minimumRecolors(char* blocks, int k) {
    int n = strlen(blocks);
    int count = 0;
    for (int i = 0; i < k; i++) {
        count += blocks[i] == 'B';
    }
    int ans = k - count;
    for (int i = k; i < n; i++) {
        count -= blocks[i - k] == 'B';
        count += blocks[i] == 'B';
        ans = min(ans, k - count);
    }
    return ans;
}

// Editorial: Just slide through the string of window size k and count the number of 'W' in the window, return the minimum number 
// of 'W' in the string.
class Solution {
public:
    int minimumRecolors(string blocks, int k) {
        int n=blocks.size();
        int i=0,j=k-1;
        int ans=n;
        while(j<n)
        {
            string s=blocks.substr(i,k);
            int cnt=count(s.begin(),s.end(),'W');
            ans=min(cnt,ans);
            i++;
            j++;
        }
        return ans;
    }
};

class Solution(object):
    def minimumRecolors(self, blocks, k):
        """
        :type blocks: str
        :type k: int
        :rtype: int
        """
        ans = float("inf")
        cnt = 0
        for i, c in enumerate(blocks):
            if c == "W":
                cnt += 1
            if i >= k and blocks[i - k] == "W":
                cnt -= 1
            if i >= k - 1:
                ans = min(ans, cnt)
        return ans
